func changeWays(coins: Array<Int64>, total: Int64): Int64 {
    let dp = Array<Int64>(total + 1, repeat: 0)
    dp[0] = 1
    for (coin in coins) {
        for (x in coin..=total) {
            dp[x] += dp[x - coin]
        }
    }
    dp[total]
}

main() {
    println(changeWays([1, 2], 4) == 3)
    println(changeWays([], 0) == 1)
}
"}

