func rotateRunes(s: String, k: Int64): String {
    let chars = s.toArray()
    let n = chars.size
    if (n == 0) {
        return ""
    }
    let offset = k % n
    var out = ""
    for (i in 0..n) {
        out += chars[(i + offset) % n].toString()
    }
    out
}

main() {
    println(rotateRunes("仓颉a", 1) == "颉a仓")
    println(rotateRunes("abc", 2) == "cab")
}
"}

