func closedSlice(a: Array<Int64>,lo: Int64,hi: Int64): Array<Int64> {
    let size = a.size
    if (size == 0) {
        return Array<Int64>()
    }
    var start = lo
    if (start < 0) {
        start = 0
    }
    var end = hi
    if (end > size - 1) {
        end = size - 1
    }
    if (start > end) {
        return Array<Int64>()
    }
    let count = end - start + 1
    let s = start
    Array<Int64>(count, {i => a[s + i]})
}

main() {
    println(closedSlice([1,2,3],0,1)==[1,2])
    println(closedSlice([1,2,3],-2,1)==[1,2])
}
"}

